    step1_desc: "Descárgalo desde github.com/Artikash/Textractor y descomprímelo en tu PC.",
    step2: "Configurar TextractorCLI",
    step2_desc: "La ruta se detecta sola si Textractor está instalado; si no, hacé clic en 'Examinar' y elegí la carpeta o el .exe directamente.",
    step3: "Elegir tu juego",
    step3_desc: "Con el juego abierto, hacé clic en 🎮 y elegilo de la lista. Tuhua lo recuerda — la próxima vez no hace falta repetirlo.",
    step4: "Se conecta solo",
    step4_desc: "Cada vez que abrís el juego, Tuhua lo reconoce y engancha Textractor automáticamente. Si lo abriste después de Tuhua, tocá 🔍 para forzar la búsqueda.",
    step5: "Un perfil por juego",
    step5_desc: "Cada juego vinculado puede tener su propio perfil — glosario, ajustes de traducción e importación de VNDB, todo separado por juego.",
    guide_alt_engine: "Si el juego dibuja el texto directamente en la GPU (Ren'Py, Godot, Unity, FNA/XNA), Textractor no puede leerlo — Tuhua lo detecta solo y te sugiere cambiar a OCR o XUAT.",
    guide_docs_link: "📖 Documentación completa: tuhua.lyca.dev",
