    guide_cb_step2_desc: "Este método sólo funciona si el juego copia el diálogo al portapapeles de Windows — por ejemplo, los juegos hechos con Ren'Py lo hacen con Shift+C. Si tu juego no tiene una función así, este método no te va a servir.",
    guide_cb_step3: "Tuhua traduce solo",
    guide_cb_step3_desc: "Apenas el texto del portapapeles cambia, Tuhua lo detecta y lo traduce en el overlay. No hay nada más que configurar.",
