    guide_ocr_step4: "Tuhua escanea y traduce",
    guide_ocr_step4_desc: "Cada pocos segundos (ajustable en Configuración) Tuhua captura esa región, lee el texto y lo traduce. Elegí el motor — Tesseract por defecto, PaddleOCR para tipografías poco comunes — también en Configuración.",
    guide_ocr_alt: "💡 Funciona con cualquier juego, incluso los que dibujan el texto directamente en pantalla (Ren'Py, Unity, Godot, FNA/XNA) sin dejar engancharse por un hook.",
