    step3: "Выберите игру",
    step3_desc: "Пока игра открыта, нажмите 🎮 и выберите её из списка. Tuhua запомнит игру — в следующий раз повторять не нужно.",
    step4: "Подключается сама",
    step4_desc: "Каждый раз, когда вы открываете игру, Tuhua узнаёт её и подключает Textractor автоматически. Если вы открыли игру после Tuhua, нажмите 🔍, чтобы запустить поиск вручную.",
    step5: "Отдельный профиль для каждой игры",
    step5_desc: "У каждой привязанной игры может быть свой профиль — глоссарий, настройки перевода и импорт из VNDB, всё отдельно по играм.",
    guide_alt_engine: "Если игра рисует текст прямо на GPU (Ren'Py, Godot, Unity, FNA/XNA), Textractor не может его прочитать — Tuhua определяет это сама и предлагает переключиться на OCR или XUAT.",
    guide_docs_link: "📖 Полная документация: tuhua.lyca.dev",
    guide_tab_textractor: "🪝 Textractor",
    guide_tab_clipboard: "📋 Буфер обмена",
    guide_tab_ocr: "📸 OCR",
    guide_tab_xuat: "🎮 XUAT",
    guide_cb_step1: "Включите Буфер обмена",
    guide_cb_step1_desc: "Выберите 📋 Буфер обмена в качестве метода ввода.",
    guide_cb_step2: "Игра должна копировать текст",
    guide_cb_step2_desc: "Этот метод работает, только если игра копирует диалог в буфер обмена Windows — например, игры на Ren'Py делают это по Shift+C. Если в вашей игре такой функции нет, этот метод не подойдёт.",
    guide_cb_step3: "Tuhua переводит сама",
    guide_cb_step3_desc: "Как только текст в буфере обмена меняется, Tuhua подхватывает его и переводит в оверлее. Больше ничего настраивать не нужно.",
    guide_cb_alt: "💡 Самый простой метод из всех, но зависит от того, есть ли у игры такая встроенная функция. Если нет — попробуйте OCR.",
    guide_ocr_step1: "Включите OCR",
    guide_ocr_step1_desc: "Выберите 📸 OCR в качестве метода ввода.",
    guide_ocr_step2: "Нажмите ▶ Активно",
    guide_ocr_step2_desc: "Поверх игры откроется прозрачное окно захвата.",
    guide_ocr_step3: "Расположите его над диалогом",
    guide_ocr_step3_desc: "Перетащите и измените размер за углы, пока окно не закроет только текстовое окно игры.",
    guide_ocr_step4: "Tuhua сканирует и переводит",
    guide_ocr_step4_desc: "Каждые несколько секунд (настраивается в Настройках) Tuhua захватывает эту область, распознаёт текст и переводит его. Движок — Tesseract по умолчанию, PaddleOCR для необычных шрифтов — тоже выбирается в Настройках.",
    guide_ocr_alt: "💡 Работает с любой игрой, даже с теми, что рисуют текст прямо на экране (Ren'Py, Unity, Godot, FNA/XNA), не оставляя ничего, за что мог бы зацепиться хук.",
    guide_xuat_step1: "Включите XUAT",
    guide_xuat_step1_desc: "Выберите 🎮 XUAT в качестве метода ввода — только для игр на Unity.",
    guide_xuat_step2: "Установите XUAT в игру",
    guide_xuat_step2_desc: "Кнопка «🎮 Установить XUAT в игру» → выберите .exe игры. Tuhua автоматически установит всё необходимое.",
    guide_xuat_step3: "Откройте игру",
