    step3_desc: "Com o jogo aberto, clique em 🎮 e escolha-o na lista. Tuhua vai lembrar — na próxima vez não precisa repetir.",
    step4: "Conecta sozinho",
    step4_desc: "Toda vez que você abrir o jogo, Tuhua o reconhece e conecta o Textractor automaticamente. Se você abriu o jogo depois do Tuhua, toque em 🔍 para forçar a busca.",
    step5: "Um perfil por jogo",
    step5_desc: "Cada jogo vinculado pode ter seu próprio perfil — glossário, configurações de tradução e importação da VNDB, tudo separado por jogo.",
    guide_alt_engine: "Se o jogo desenha o texto direto na GPU (Ren'Py, Godot, Unity, FNA/XNA), o Textractor não consegue ler — o Tuhua detecta isso sozinho e sugere mudar para OCR ou XUAT.",
    guide_docs_link: "📖 Documentação completa: tuhua.lyca.dev",
    guide_tab_textractor: "🪝 Textractor",
    guide_tab_clipboard: "📋 Área de Transferência",
    guide_tab_ocr: "📸 OCR",
    guide_tab_xuat: "🎮 XUAT",
    guide_cb_step1: "Ative a Área de Transferência",
    guide_cb_step1_desc: "Escolha 📋 Área de Transferência como método de entrada.",
    guide_cb_step2: "O jogo precisa copiar o texto",
    guide_cb_step2_desc: "Esse método só funciona se o jogo copiar o diálogo para a área de transferência do Windows — jogos feitos em Ren'Py fazem isso com Shift+C, por exemplo. Se o seu jogo não tiver essa função, esse método não vai funcionar para ele.",
    guide_cb_step3: "O Tuhua traduz sozinho",
    guide_cb_step3_desc: "Assim que o texto da área de transferência mudar, o Tuhua detecta e traduz no overlay. Não há mais nada para configurar.",
    guide_cb_alt: "💡 É o método mais simples de todos, mas depende do jogo ter essa função nativa. Se não tiver, tente o OCR.",
    guide_ocr_step1: "Ative o OCR",
    guide_ocr_step1_desc: "Escolha 📸 OCR como método de entrada.",
    guide_ocr_step2: "Toque em ▶ Ativo",
    guide_ocr_step2_desc: "Uma janela transparente de captura se abre sobre o jogo.",
    guide_ocr_step3: "Posicione sobre o diálogo",
    guide_ocr_step3_desc: "Arraste e redimensione pelos cantos até cobrir só a caixa de texto do jogo.",
    guide_ocr_step4: "O Tuhua escaneia e traduz",
    guide_ocr_step4_desc: "A cada poucos segundos (ajustável em Configurações) o Tuhua captura essa região, lê o texto e traduz. Escolha o motor — Tesseract por padrão, PaddleOCR para fontes incomuns — também em Configurações.",
    guide_ocr_alt: "💡 Funciona com qualquer jogo, até os que desenham o texto direto na tela (Ren'Py, Unity, Godot, FNA/XNA) sem nada para um hook agarrar.",
    guide_xuat_step1: "Ative o XUAT",
    guide_xuat_step1_desc: "Escolha 🎮 XUAT como método de entrada — apenas para jogos em Unity.",
    guide_xuat_step2: "Instale o XUAT no jogo",
    guide_xuat_step2_desc: "Botão '🎮 Instalar XUAT em um Jogo' → escolha o .exe do jogo. O Tuhua instala tudo automaticamente.",
    guide_xuat_step3: "Abra o jogo",
    guide_xuat_step3_desc: "O Tuhua substitui o texto direto dentro do jogo — não precisa de overlay, a tradução aparece na própria janela do jogo.",
    guide_xuat_alt: "💡 O método recomendado para jogos em Unity (principalmente IL2CPP), onde o Textractor não consegue um hook real.",
