    step5: "Un profilo per gioco",
    step5_desc: "Ogni gioco collegato può avere un proprio profilo — glossario, impostazioni di traduzione e importazione da VNDB, tutto separato per gioco.",
    guide_alt_engine: "Se il gioco disegna il testo direttamente sulla GPU (Ren'Py, Godot, Unity, FNA/XNA), Textractor non può leggerlo — Tuhua lo rileva da solo e suggerisce di passare a OCR o XUAT.",
    guide_docs_link: "📖 Documentazione completa: tuhua.lyca.dev",
