    guide_cb_step2_desc: "Questo metodo funziona solo se il gioco copia il dialogo negli appunti di Windows — i giochi Ren'Py lo fanno con Shift+C, per esempio. Se il tuo gioco non ha questa funzione, questo metodo non farà per lui.",
    guide_cb_step3: "Tuhua traduce da solo",
    guide_cb_step3_desc: "Appena il testo negli appunti cambia, Tuhua lo rileva e lo traduce nell'overlay. Non c'è altro da configurare.",
    guide_cb_alt: "💡 Il metodo più semplice di tutti, ma dipende dal fatto che il gioco abbia questa funzione nativa. Se non ce l'ha, prova l'OCR.",
