    guide_ocr_step4_desc: "Ogni pochi secondi (regolabile in Impostazioni) Tuhua cattura quella regione, legge il testo e lo traduce. Scegli il motore — Tesseract di default, PaddleOCR per font insoliti — sempre in Impostazioni.",
    guide_ocr_alt: "💡 Funziona con qualsiasi gioco, anche con quelli che disegnano il testo direttamente sullo schermo (Ren'Py, Unity, Godot, FNA/XNA) senza nulla a cui un hook possa agganciarsi.",
