    guide_alt_engine: "ゲームがテキストをGPU上に直接描画する場合(Ren'Py、Godot、Unity、FNA/XNA)、Textractorは読み取れません — Tuhuaが自動で検出し、OCRまたはXUATへの切り替えを提案します。",
