    guide_cb_step3: "Tuhuaが自動で翻訳",
    guide_cb_step3_desc: "クリップボードのテキストが変わるとすぐにTuhuaが検知し、オーバーレイで翻訳します。他に設定は必要ありません。",
    guide_cb_alt: "💡 一番シンプルな方法ですが、ゲーム側にその機能があることが前提です。ない場合はOCRを試してください。",
